def transform(grid):
    h, w = len(grid), len(grid[0])
    # The source motif is the contiguous non-background run on its own row.
    background = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    motif = None
    for row in grid:
        runs = []
        start = None
        for c, value in enumerate(row + [background]):
            if value != background and start is None:
                start = c
            elif value == background and start is not None:
                runs.append(row[start:c])
                start = None
        if runs:
            motif = max(runs, key=len)
            break
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        if row == grid[-1] and r == h - 1:
            continue
        for c, value in enumerate(row):
            if value == 6:
                for j, v in enumerate(motif):
                    cc = c - 2 + j
                    if 0 <= cc < w:
                        out[r][cc] = v
    return out

